export default function ({ body, previous }) {
  if (
    !body ||
    !Array.isArray(body.items) ||
    !(body.bookmark == null || typeof body.bookmark === "string")
  )
    throw Error("Invalid Pinterest page");
  const rows = [...(previous?.rows ?? []), ...body.items];
  if (rows.length > 10000) throw Error("Too many pins");
  return {
    state: { rows },
    more: !!body.bookmark,
    bookmark: body.bookmark ?? "",
    url:
      "https://api.pinterest.com/v5/pins?page_size=100" +
      (body.bookmark ? "&bookmark=" + encodeURIComponent(body.bookmark) : ""),
  };
}

