export default function ({ items, previous }) {
  const i = (previous?.i ?? -1) + 1;
  if (i >= items.length) return { state: { i }, more: false, pin: {} };
  let p = items[i];
  if (!p || typeof p.id !== "string" || !p.id) throw Error("Pin missing ID");
  return {
    state: { i },
    more: true,
    pin: {
      pin_id: p.id,
      created_at: p.created_at ?? "",
      title: p.title ?? "",
      description: p.description ?? "",
      link: p.link ?? "",
      type: "Organic",
    },
  };
}

