export default function ({ records, pin }) {
  if (records.length > 1) throw Error("Duplicate pin_id in Airtable");
  const fields = pin;
  return {
    found: records.length === 1,
    create: [{ fields }],
    update: [{ id: records[0]?.id ?? "rec00000000000000", fields }],
  };
}

