export default async function ({ pin, scheduledAt }, ctx) {
  const key = "pinterest:" + scheduledAt + ":" + pin.pin_id,
    s = await ctx.state.get(key);
  if (s?.status === "pending") throw Error("Inspect Airtable before resolving unknown write");
  if (s?.status === "done") return { key, skip: true };
  await ctx.state.set(key, { status: "pending" });
  return { key, skip: false };
}

