export default function collect({ records, offset, previous }) {
  if (!Array.isArray(records)) throw Error("Invalid Airtable page");
  return {
    state: { records: [...(previous?.records ?? []), ...records] },
    more: !!offset,
    offset: offset ?? null,
  };
}

